<script setup>
import { computed, ref } from 'vue';
import { ATTRIBUTION_NOTICE, attributedMetricCards, campaignLifecycleLabel } from '../../../domain/marketing.js';
import Icon from '../../ui/EditionIcon.vue';
import Modal from '../../ui/EditionModal.vue';

const props=defineProps({campaigns:{type:Array,default:()=>[]},analytics:{type:Object,default:null},currency:{type:String,default:'RM'},canManage:Boolean,busy:Boolean,error:{type:String,default:''}});
const emit=defineEmits(['new','edit','transition','clone','analytics','close-analytics']);
const status=ref(''),query=ref('');
const filtered=computed(()=>props.campaigns.filter(row=>(!status.value||row.status===status.value)&&(!query.value.trim()||row.name.toLowerCase().includes(query.value.trim().toLowerCase()))));
const cards=computed(()=>attributedMetricCards(props.analytics?.metrics||{},props.currency,props.analytics?.customerCohort));
const stamp=value=>value?new Intl.DateTimeFormat('en-MY',{dateStyle:'medium',timeZone:'Asia/Kuala_Lumpur'}).format(new Date(value)):'No expiry';
const actionsFor=row=>({draft:['publish','archive'],published:['pause','complete'],paused:['publish','complete','archive'],completed:['archive'],archived:[]}[row.lifecycle]||[]);
const actionLabel=action=>({publish:'Publish',pause:'Pause',complete:'Complete',archive:'Archive'})[action];
</script>

<template>
  <section class="mf-campaigns-panel">
    <div class="ed-section-head"><div><div class="ed-eyebrow">CAMPAIGNS</div><h2>Plan, publish and learn</h2><small>Each campaign keeps exact audience and offer versions for reliable history.</small></div><button v-if="canManage" class="ed-btn primary" @click="emit('new')"><Icon name="plus"/>New campaign</button></div>
    <div class="ed-filters"><input v-model="query" class="ed-input" aria-label="Search campaigns" placeholder="Search campaign"><label class="ed-field ed-filter-field"><span>Lifecycle</span><select v-model="status"><option value="">All states</option><option v-for="value in ['draft','scheduled','active','paused','completed','archived']" :key="value" :value="value">{{ campaignLifecycleLabel(value) }}</option></select></label><span class="ed-muted">{{ filtered.length }} campaign{{ filtered.length===1?'':'s' }}</span></div>
      <div class="mf-campaign-list"><article v-for="row in filtered" :key="row.id"><div class="mf-campaign-state" :class="row.status"></div><div class="mf-campaign-main"><div class="ed-eyebrow">{{ row.objective?.replaceAll('_',' ')||row.goal?.replaceAll('_',' ') }} · VERSION {{ row.version }}</div><h3>{{ row.name }}</h3><p>{{ row.description||'No campaign description.' }}</p><div class="mf-campaign-meta"><span><Icon name="clock"/>{{ stamp(row.startsAt) }} – {{ stamp(row.endsAt) }}</span><span><Icon name="grid"/>{{ row.channels?.join(', ')||'No channel' }}</span><span><Icon name="people"/>{{ row.audienceLinks?.length||0 }} audience link{{ row.audienceLinks?.length===1?'':'s' }}</span><span><Icon name="percent"/>{{ row.promotionLinks?.length||0 }} offer link{{ row.promotionLinks?.length===1?'':'s' }}<template v-if="row.bonusPoints"> + {{ row.bonusPoints }} points</template></span></div></div><div class="mf-campaign-side"><span class="ed-pill" :class="{ready:row.status==='active',warning:row.status==='scheduled'}">{{ campaignLifecycleLabel(row.status) }}</span><div class="ed-actions"><button class="ed-btn small" @click="emit('analytics',row)"><Icon name="chart"/>Results</button><button v-if="canManage&&['draft','paused'].includes(row.lifecycle)" class="ed-btn small" @click="emit('edit',row)">Edit</button><button v-for="action in canManage?actionsFor(row):[]" :key="action" class="ed-btn small" :class="{primary:['publish','pause'].includes(action),danger:action==='archive'}" @click="emit('transition',{campaign:row,action})">{{ actionLabel(action) }}</button><button v-if="canManage" class="ed-btn small" @click="emit('clone',row)">Clone</button></div></div></article></div>
    <div v-if="!filtered.length" class="ed-empty"><Icon name="spark"/><h3>{{ campaigns.length?'No campaign matches these filters.':'No campaigns yet.' }}</h3><p>{{ campaigns.length?'Clear the filters to see the rest.':'Create a draft to define the goal, audience, offer, channel and limits.' }}</p></div>
    <p v-if="error&&!analytics" class="ed-notice error">{{ error }}</p>
    <Modal v-if="analytics" :title="`${analytics.campaignName||'Campaign'} · attributed results`" wide :busy="busy" @close="emit('close-analytics')"><div class="mf-analytics-cards"><article v-for="card in cards" :key="card.key"><span>{{ card.label }}</span><strong>{{ card.value }}</strong></article></div><div class="ed-notice"><Icon name="chart"/><div><strong>{{ analytics.attribution?.label||'Attributed performance' }}</strong>{{ analytics.attribution?.limitation||ATTRIBUTION_NOTICE }}</div></div><div v-if="analytics.orderLifecycle" class="mf-lifecycle-grid"><article v-for="(value,key) in analytics.orderLifecycle" :key="key"><span>{{ key.replaceAll('_',' ') }}</span><strong>{{ value }}</strong></article></div><p v-if="error" class="ed-notice error">{{ error }}</p><template #actions><span class="ed-muted">{{ analytics.from }} – {{ analytics.to }}</span><button class="ed-btn" @click="emit('close-analytics')">Close</button></template></Modal>
  </section>
</template>

<style scoped>
.mf-campaigns-panel{display:grid;gap:20px}.mf-campaign-list{display:grid;gap:11px}.mf-campaign-list>article{display:grid;grid-template-columns:5px minmax(0,1fr) auto;gap:17px;border:1px solid var(--ed-line);background:var(--ed-paper);padding:18px}.mf-campaign-state{background:#999}.mf-campaign-state.active{background:#238258}.mf-campaign-state.scheduled{background:#ce9228}.mf-campaign-state.paused{background:#9c733e}.mf-campaign-state.completed{background:#69756e}.mf-campaign-main h3{font:400 25px var(--ed-font-sans);margin:7px 0}.mf-campaign-main p{font-size:11px;color:var(--ed-muted);margin:0}.mf-campaign-meta{display:flex;flex-wrap:wrap;gap:13px;margin-top:14px}.mf-campaign-meta span{display:flex;align-items:center;gap:5px;font-size:9px;color:var(--ed-muted)}.mf-campaign-side{display:flex;flex-direction:column;align-items:flex-end;justify-content:space-between;gap:18px}.mf-analytics-cards,.mf-lifecycle-grid{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--ed-line);margin-bottom:18px}.mf-analytics-cards article,.mf-lifecycle-grid article{padding:16px;border-right:1px solid var(--ed-line);display:grid;gap:7px}.mf-analytics-cards span,.mf-lifecycle-grid span{font-size:9px;color:var(--ed-muted);text-transform:uppercase}.mf-analytics-cards strong,.mf-lifecycle-grid strong{font:400 24px var(--ed-font-sans)}.mf-lifecycle-grid{margin-top:18px}.mf-lifecycle-grid article:nth-child(4n){border-right:0}@media(max-width:800px){.mf-campaign-list>article{grid-template-columns:4px 1fr}.mf-campaign-side{grid-column:2;align-items:flex-start}.mf-analytics-cards,.mf-lifecycle-grid{grid-template-columns:repeat(2,1fr)}}
</style>
